// ---------- runtime ----------
window.SYMPHONY_LANGS = ["en", "zh-Hans", "ja", "id", "vi"];
window.symphonyLang = (function () {
  try {
    const saved = localStorage.getItem("symphony-lang");
    if (saved && window.I18N[saved]) return saved;
  } catch (e) {}
  return "en";
})();
window.t = function (key, vars) {
  const dict = window.I18N[window.symphonyLang] || window.I18N.en;
  let s = dict[key] || window.I18N.en[key] || key;
  if (vars) for (const k of Object.keys(vars)) s = s.replaceAll("{" + k + "}", String(vars[k]));
  return s;
};
window.applyI18n = function () {
  document.documentElement.lang = window.symphonyLang;
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    el.textContent = window.t(el.getAttribute("data-i18n"));
  });
  document.querySelectorAll("[data-i18n-aria]").forEach((el) => {
    el.setAttribute("aria-label", window.t(el.getAttribute("data-i18n-aria")));
  });
  const sel = document.getElementById("langSelect");
  if (sel) sel.value = window.symphonyLang;
};
window.setSymphonyLang = function (lang) {
  if (!window.I18N[lang]) return;
  window.symphonyLang = lang;
  try { localStorage.setItem("symphony-lang", lang); } catch (e) {}
  window.applyI18n();
  document.dispatchEvent(new CustomEvent("symphony-lang-changed"));
};
document.addEventListener("DOMContentLoaded", function () {
  const sel = document.getElementById("langSelect");
  if (sel) sel.addEventListener("change", () => window.setSymphonyLang(sel.value));
  window.applyI18n();
});
